<template>
  <main class="bom-page" :aria-busy="busy">
    <header><div><h1>版本化 BOM</h1><p>按发生位置维护工程与制造结构，保留准确材料来源和每次修改。</p></div><button :disabled="busy" @click="reload">刷新</button></header>
    <p v-if="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
    <section v-if="pending"><p>上次保存结果尚未确认，请先恢复原操作。</p><button :disabled="busy" @click="recover(false)">查询原操作</button><button :disabled="busy" @click="recover(true)">结束未提交操作</button></section>
    <section><header><h2>结构目录</h2><button v-if="permissions.has('plm-engineering-bom:add')" :disabled="locked || !scope" @click="newBom">新建 BOM</button></header>
      <form class="inline" @submit.prevent="loadPage(1)"><label>名称<input v-model="search" aria-label="BOM搜索" :disabled="busy" maxlength="256" /></label><button :disabled="busy || !canRead">搜索</button></form>
      <div class="scroll"><table><thead><tr><th>名称</th><th>视图</th><th>版本</th><th>位置数</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.reference.id"><td>{{ row.body.name }}</td><td>{{ row.body.kind }}</td><td>{{ row.reference.version }}</td><td>{{ row.body.occurrences.length }}</td><td><button :disabled="busy" @click="open(row.reference.id)">打开 BOM</button></td></tr></tbody></table></div>
      <p v-if="!rows.length">当前范围内没有结构。</p><nav><button :disabled="busy || page === 1" @click="loadPage(page - 1)">上一页</button><span>第 {{ page }} 页</span><button :disabled="busy || rows.length < 20" @click="loadPage(page + 1)">下一页</button></nav>
    </section>
    <section v-if="editing"><h2>{{ current ? '修订结构' : '新建结构草稿' }}</h2><p>草稿尚未评审或冻结。材料、单位和替代关系的缺项必须明确处理。</p>
      <form class="inline" @submit.prevent="findParents"><label>工程修订编号<input v-model="parentSearch" aria-label="工程修订搜索" :disabled="locked" /></label><button :disabled="locked">查找工程修订</button></form>
      <label>准确工程修订<select aria-label="工程修订选择" :disabled="locked || !canWrite" :value="''" @change="chooseParent(($event.target as HTMLSelectElement).value)"><option value="">请选择当前修订与产品版本</option><option v-for="p in parents" :key="key(p.reference)" :value="key(p.reference)">{{ p.revisionCode }} · v{{ p.reference.version }} · {{ p.draft.goal }}</option></select></label>
      <p v-if="body">来源修订 {{ body.revisionOrigin.id }} · v{{ body.revisionOrigin.version }}。修订来源更新时，已录入结构会保留。</p>
      <ul v-if="current?.missing.length" aria-label="BOM缺项"><li v-for="item in current.missing" :key="item">{{ finding(item) }}</li></ul>
      <form v-if="body" @submit.prevent="save"><fieldset :disabled="locked || !canWrite"><div class="grid">
        <label>名称<input v-model="body.name" aria-label="BOM名称" required maxlength="256" /></label><label>视图<select v-model="body.kind" aria-label="BOM视图" :disabled="!!current"><option value="EBOM">工程结构 EBOM</option><option value="MBOM">制造结构 MBOM</option></select></label>
        <label>修改原因<textarea v-model="reason" aria-label="BOM修改原因" required maxlength="4000" /></label>
        <label>场所<select :value="body.siteRef ? key(body.siteRef) : ''" aria-label="BOM场所" @change="chooseSite(($event.target as HTMLSelectElement).value)"><option value="">待确认</option><option v-if="body.siteRef && !sites.some(s => key(s.reference) === key(body!.siteRef!))" :value="key(body.siteRef)">已保存场所 · v{{ body.siteRef.version }}</option><option v-for="s in sites" :key="key(s.reference)" :value="key(s.reference)">{{ s.code }} / {{ s.name }} · v{{ s.reference.version }}</option></select></label>
        <label>工艺版本<select :value="body.routingRef ? key(body.routingRef) : ''" aria-label="BOM工艺" @change="chooseRouting(($event.target as HTMLSelectElement).value)"><option value="">待确认</option><option v-if="body.routingRef && !routes.some(r => key(r.reference) === key(body!.routingRef!))" :value="key(body.routingRef)">已保存工艺 · v{{ body.routingRef.version }}</option><option v-for="r in routes" :key="key(r.reference)" :value="key(r.reference)">{{ r.body.name }} · v{{ r.reference.version }}</option></select></label>
      </div><button type="button" @click="findSites">查找场所</button><button type="button" @click="findRoutes">查找本修订工艺</button>
      <article v-for="(line, index) in body.occurrences" :key="line.occurrenceId" class="occurrence"><header><h3>位置 {{ index + 1 }} · {{ line.name }}</h3><button type="button" @click="body.occurrences.splice(index, 1)">移除位置</button></header>
        <div class="grid"><label>位置名称<input v-model="line.name" :aria-label="`位置名称 ${index + 1}`" maxlength="256" required /></label><label>可追溯路径<input v-model="line.path" :aria-label="`位置路径 ${index + 1}`" maxlength="2048" required /></label>
          <label>父位置<select v-model="line.parentOccurrenceId" :aria-label="`父位置 ${index + 1}`"><option :value="null">根结构下</option><option v-for="p in body.occurrences.filter(p => p.occurrenceId !== line.occurrenceId)" :key="p.occurrenceId" :value="p.occurrenceId">{{ p.path }} / {{ p.name }}</option><option v-if="line.parentOccurrenceId && !body.occurrences.some(p => p.occurrenceId === line.parentOccurrenceId)" :value="line.parentOccurrenceId">已移除父位置</option></select></label>
          <label>同级顺序<input v-model.number="line.semanticOrder" :aria-label="`位置顺序 ${index + 1}`" type="number" min="0" step="1" required /></label>
          <label>准确材料<select :value="line.itemRef ? key(line.itemRef) : ''" :aria-label="`位置材料 ${index + 1}`" @change="chooseItem(line, ($event.target as HTMLSelectElement).value)"><option value="">材料待解析</option><option v-if="line.itemRef && !items.some(i => key(i.reference) === key(line.itemRef!))" :value="key(line.itemRef)">已保存材料 · v{{ line.itemRef.version }}</option><option v-for="i in items" :key="key(i.reference)" :value="key(i.reference)">{{ i.code }} / {{ i.name }} · v{{ i.reference.version }}</option></select></label>
          <label>用量<input :value="line.quantity ?? ''" :aria-label="`用量 ${index + 1}`" inputmode="decimal" maxlength="2050" @input="line.quantity = ($event.target as HTMLInputElement).value || null" /></label>
          <label>单位<select :value="line.unitRef ? key(line.unitRef) : ''" :aria-label="`位置单位 ${index + 1}`" @change="chooseUnit(line, ($event.target as HTMLSelectElement).value)"><option value="">单位待确认</option><option v-if="line.unitRef && !units.some(u => key(u.reference) === key(line.unitRef!))" :value="key(line.unitRef)">已保存单位 · v{{ line.unitRef.version }}</option><option v-for="u in units" :key="key(u.reference)" :value="key(u.reference)">{{ u.profile.code }} / {{ u.profile.dimensionKey }} · v{{ u.reference.version }}</option></select></label>
          <label>用量基准与依据<textarea v-model="line.quantityBasis" :aria-label="`用量依据 ${index + 1}`" maxlength="4000" /></label><label>损耗<input :value="line.loss ?? ''" :aria-label="`损耗 ${index + 1}`" inputmode="decimal" maxlength="2050" @input="line.loss = ($event.target as HTMLInputElement).value || null" /></label><label>损耗基准与依据<textarea v-model="line.lossBasis" maxlength="4000" /></label>
          <label>适用性<select v-model="line.applicability"><option value="UNKNOWN">待确定</option><option value="APPLIES">拟适用</option><option value="NOT_APPLICABLE">拟不适用</option></select></label><label>适用依据<textarea v-model="line.reason" :required="line.applicability === 'NOT_APPLICABLE'" maxlength="8000" /></label>
          <label>配置条件<textarea v-model="line.configurationCondition" maxlength="4000" /></label><label>替代要求<textarea v-model="line.substitutionRequirement" maxlength="4000" /></label>
          <label>投入工艺位置<select v-model="line.routingOccurrenceId" :aria-label="`投入工序 ${index + 1}`"><option :value="null">待确认</option><option v-if="line.routingOccurrenceId && !routeSteps.some(s => s.occurrenceId === line.routingOccurrenceId)" :value="line.routingOccurrenceId">原位置待核对</option><option v-for="s in routeSteps" :key="s.occurrenceId" :value="s.occurrenceId">{{ s.semanticOrder }} / {{ s.name }}</option></select></label>
          <label>说明<textarea v-model="line.note" :aria-label="`位置说明 ${index + 1}`" maxlength="8000" /></label></div>
      </article><button type="button" @click="addOccurrence">添加结构位置</button><button>保存 BOM 版本</button></fieldset></form>
    </section>
    <section v-if="editing"><h2>准确来源与使用位置</h2><p>经营材料和工程产品保持各自身份；单位的存在不代表该用量或换算已经批准。</p>
      <form class="inline" @submit.prevent="findItems(1)"><label>材料来源<select v-model="itemKind" :disabled="locked"><option value="BUSINESS">经营产品</option><option value="ENGINEERING">工程产品</option></select></label><label>材料编码<input v-model="itemSearch" aria-label="材料搜索" :disabled="locked" /></label><button :disabled="locked">查找材料</button><button type="button" :disabled="locked || !moreItems" @click="findItems(itemPage + 1)">更多材料</button></form>
      <form class="inline" @submit.prevent="findUnits(1)"><label>单位编码<input v-model="unitSearch" aria-label="单位搜索" :disabled="locked" /></label><button :disabled="locked">查找单位</button><button type="button" :disabled="locked || !moreUnits" @click="findUnits(unitPage + 1)">更多单位</button></form>
      <label>查询材料使用位置<select v-model="usageChoice" aria-label="使用位置材料" :disabled="busy"><option value="">请选择准确材料版本</option><option v-for="i in items" :key="key(i.reference)" :value="key(i.reference)">{{ i.code }} · v{{ i.reference.version }}</option></select></label><button :disabled="busy || !usageChoice" @click="findUsage(1)">查询使用位置</button><button :disabled="busy || !usageChoice" @click="findUsage(usagePage + 1)">继续查询结构</button>
      <ul><li v-for="u in usages" :key="`${key(u.bomRef)}:${u.occurrenceId}`">{{ u.kind }} / {{ u.name }} · v{{ u.bomRef.version }} · {{ u.path }}</li></ul><p v-if="usageQueried && !usages.length">当前权限范围内，本页没有该版本的使用位置。</p>
      <h3>导入现有材料定义</h3><button :disabled="locked || !body || !canWrite" @click="findMappings">查找确认映射</button><label>经营产品映射<select v-model="mappingChoice" aria-label="BOM导入映射" :disabled="locked || !canWrite"><option value="">请选择</option><option v-for="m in mappings" :key="key(m.reference)" :value="key(m.reference)">{{ m.candidate.purpose }} · {{ m.candidate.businessRef?.id }} · v{{ m.reference.version }}</option></select></label><button :disabled="locked || !mappingChoice || !canWrite" @click="previewLegacy">预览现有材料</button>
      <div v-if="preview"><p>原件 {{ preview.rows.length }} 行。采用后替换本页结构；材料编号和单位文本仍需解析为准确来源。</p><ol><li v-for="line in preview.suggestedOccurrences" :key="line.occurrenceId">{{ line.name }} · {{ line.quantity ?? '用量待确认' }}</li></ol><button :disabled="locked || !canWrite" @click="adoptLegacy">采用预览位置</button></div>
    </section>
    <section v-if="current"><h2>历史与差异</h2><form class="inline" @submit.prevent="readHistory"><label>历史版本<input v-model="historyVersion" aria-label="BOM历史版本" pattern="[1-9][0-9]*" required /></label><button :disabled="busy">读取历史</button></form>
      <div v-if="history"><h3>{{ history.body.name }} · v{{ history.reference.version }}</h3><ol><li v-for="line in history.body.occurrences" :key="line.occurrenceId">{{ line.path }} / {{ line.name }} / {{ line.quantity }}</li></ol><details><summary>保存的原件</summary><pre>{{ history.originalJson }}</pre></details></div>
      <form class="inline" @submit.prevent="readDiff"><label>起始版本<input v-model="beforeVersion" aria-label="BOM差异起始版本" pattern="[1-9][0-9]*" required /></label><label>结束版本<input v-model="afterVersion" aria-label="BOM差异结束版本" pattern="[1-9][0-9]*" required /></label><button :disabled="busy">比较版本</button></form><details v-for="change in diff?.changes" :key="change.path"><summary>{{ change.path }}</summary><div class="grid"><pre>{{ change.before }}</pre><pre>{{ change.after }}</pre></div></details>
    </section>
  </main>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { bomApi, type BomBody, type BomSnapshot, type BomLegacy, type BomOccurrence, type BomCommand, type BomItemChoice, type BomUsage } from '@/api/plm/engineeringBom'
import { revisionApi, type RevisionSnapshot, type RevisionDiff } from '@/api/plm/engineeringRevisions'
import { routingApi, type RoutingSnapshot } from '@/api/plm/engineeringRouting'
import { engineeringApi, type EngineeringReference, type EngineeringScope, type MappingVersion, type SourceChoice } from '@/api/plm/engineeringProducts'
import { uomApi, type UomVersion } from '@/api/erp/uomProfiles'
import { pendingBom, bomResponse as result, saveBom, resolveBom, type PendingBom } from '@/auth/engineeringBomRecovery'
import { AUTH_EVENT, identityStamp, requireIdentity } from '@/auth/identity'
import { authenticationCanRead } from '@/auth/browserAuthentication'
import { usePermissionStore } from '@/stores/permission'
const permissions = usePermissionStore(), canRead = computed(() => permissions.loaded && permissions.has('plm-engineering-bom:query'))
const canWrite = computed(() => canRead.value && permissions.has(`plm-engineering-bom:${current.value ? 'edit' : 'add'}`))
const busy = ref(false), error = ref(''), notice = ref(''), scope = ref<EngineeringScope | null>(null), pending = ref<PendingBom | null>(null), locked = computed(() => busy.value || !!pending.value)
const rows = ref<BomSnapshot[]>([]), search = ref(''), page = ref(1), current = ref<BomSnapshot | null>(null), body = ref<BomBody | null>(null), editing = ref(false), id = ref(''), reason = ref('')
const parentSearch = ref(''), parents = ref<RevisionSnapshot[]>([]), sites = ref<SourceChoice[]>([]), routes = ref<RoutingSnapshot[]>([]), items = ref<BomItemChoice[]>([]), units = ref<UomVersion[]>([])
const itemKind = ref('BUSINESS'), itemSearch = ref(''), itemPage = ref(1), moreItems = ref(false), unitSearch = ref(''), unitPage = ref(1), moreUnits = ref(false)
const usages = ref<BomUsage[]>([]), usageChoice = ref(''), usagePage = ref(1), usageQueried = ref(false)
const mappings = ref<MappingVersion[]>([]), mappingChoice = ref(''), preview = ref<BomLegacy | null>(null), adopted = ref<BomLegacy | null>(null)
const history = ref<BomSnapshot | null>(null), historyVersion = ref('1'), beforeVersion = ref('1'), afterVersion = ref('1'), diff = ref<RevisionDiff | null>(null)
const copy = <T,>(v: T): T => JSON.parse(JSON.stringify(v)) as T
const key = (v: EngineeringReference) => `${v.owner}:${v.id}:${v.version}:${v.digest}`
const routeSteps = computed(() => routes.value.find(r => body.value?.routingRef && key(r.reference) === key(body.value.routingRef))?.body.operations ?? [])
let generation = 0, live = true
function finding(s: string) {
  const labels: Record<string, string> = { OCCURRENCES_REQUIRED: '结构位置待补齐', ITEM_REQUIRED: '材料准确来源待解析', UNIT_REQUIRED: '单位待确认', QUANTITY_REQUIRED: '用量待补齐', QUANTITY_NONPOSITIVE: '用量非正数，待核准', QUANTITY_BASIS_REQUIRED: '用量基准与依据待补齐', QUANTITY_APPLICATION_REVIEW_REQUIRED: '用量及单位适用关系待评审', QUANTITY_UNIT_PRECISION_CONFLICT: '用量精度与单位不符', LOSS_NEGATIVE: '负损耗待核准', LOSS_BASIS_REQUIRED: '损耗基准待补齐', STRUCTURE_CYCLE: '结构存在循环', ITEM_SELF_CONTAINMENT: '材料存在自包含', PARENT_OCCURRENCE_MISSING: '父位置已缺失', APPLICABILITY_REVIEW_REQUIRED: '配置适用性待评审', SUBSTITUTION_APPROVAL_REQUIRED: '替代要求待批准', ITEM_TECHNICAL_REVISION_REQUIRED: '经营材料的技术修订待确认', ROUTING_OCCURRENCE_MISSING: '投入工艺位置待核对', ROUTING_REVIEW_AND_FREEZE_REQUIRED: '工艺尚待评审冻结', MANUFACTURING_MAPPING_REVIEW_REQUIRED: '制造映射与差异待评审', LEGACY_TECHNICAL_REVIEW_REQUIRED: '旧材料定义待技术复核', SITE_REQUIRED: '场所待确认', ROUTING_REQUIRED: '工艺待确认', ROUTING_SITE_MISMATCH: '工艺与结构场所不一致' }
  const code = s.split(':')[0] ?? s; return labels[code] || (code.endsWith('SOURCE_CHANGED') ? '引用来源已变化，请重新核对' : '来源或资格待核准')
}
function clearEditor() { current.value = null; body.value = null; editing.value = false; id.value = ''; reason.value = ''; parents.value = []; parentSearch.value = ''; sites.value = []; routes.value = []; items.value = []; units.value = []; usages.value = []; usageChoice.value = ''; usageQueried.value = false; mappings.value = []; mappingChoice.value = ''; preview.value = null; adopted.value = null; history.value = null; diff.value = null; itemSearch.value = ''; unitSearch.value = ''; moreItems.value = moreUnits.value = false }
function clearPrivate() { clearEditor(); rows.value = []; search.value = ''; page.value = 1 }
function syncPending() { pending.value = scope.value ? pendingBom(scope.value) : null }
async function run(action: (check: () => void) => Promise<void>) {
  if (busy.value) return
  const stamp = identityStamp(), epoch = generation
  const check = () => { requireIdentity(stamp); if (!live || generation !== epoch || !authenticationCanRead()) throw new Error('当前身份已变化。') }
  busy.value = true; error.value = ''; notice.value = ''
  try { check(); await action(check); check() }
  catch (failure: any) { try { check(); const status = failure?.response?.status; if ([401, 403].includes(status)) clearPrivate(); error.value = [401, 403].includes(status) ? '当前无权读取结构或引用来源。' : status === 412 ? '结构或来源版本已变化，请查询原操作后重新核对。' : /^[A-Z][A-Z0-9_]+$/.test(failure?.response?.data?.message || '') ? '请核对输入、来源和原操作状态。' : failure?.message || '操作结果尚未确认。' } catch { /* Ignore old identity responses. */ } }
  finally { try { check(); syncPending(); busy.value = false } catch { if (live && epoch === generation) busy.value = false } }
}
function setCurrent(value: BomSnapshot) { clearEditor(); current.value = value; body.value = copy(value.body); editing.value = true; id.value = value.reference.id; afterVersion.value = value.reference.version }
async function reload() { await run(async check => { clearPrivate(); scope.value = null; if (!permissions.loaded) await permissions.loadMyActions(); check(); if (!canRead.value) throw new Error('当前没有读取结构的权限。'); const s = result(await bomApi.scope()); check(); scope.value = s; const list = result(await bomApi.list()); check(); rows.value = list }) }
async function loadPage(target: number) { await run(async check => { rows.value = []; const list = result(await bomApi.list(undefined, search.value, target)); check(); rows.value = list; page.value = target }) }
async function open(value: string) { await run(async check => { clearEditor(); const saved = result(await bomApi.read(value)); check(); if (saved.tenantId !== scope.value?.tenantId) throw new Error('租户已变化。'); setCurrent(saved) }) }
function newBom() { if (locked.value) return; clearEditor(); editing.value = true; id.value = crypto.randomUUID() }
async function findParents() { await run(async check => { parents.value = []; const values = result(await revisionApi.list(parentSearch.value)); check(); parents.value = values.filter(p => p.isCurrent && p.state === 'DRAFT' && p.draft.productRef && (!current.value || p.reference.id === current.value.body.revisionOrigin.id)) }) }
function chooseParent(selected: string) { if (locked.value || !canWrite.value) return; const p = parents.value.find(p => key(p.reference) === selected); if (!p?.draft.productRef) return; body.value = body.value ? { ...body.value, revisionOrigin: copy(p.reference), productRef: copy(p.draft.productRef) } : { name: '', kind: 'EBOM', revisionOrigin: copy(p.reference), productRef: copy(p.draft.productRef), siteRef: null, routingRef: null, occurrences: [] }; preview.value = adopted.value = null; routes.value = [] }
function addOccurrence() { if (!body.value) return; body.value.occurrences.push({ occurrenceId: crypto.randomUUID(), parentOccurrenceId: null, path: '', semanticOrder: Math.max(0, ...body.value.occurrences.map(o => o.semanticOrder)) + 10, name: '', itemRef: null, quantity: null, unitRef: null, quantityBasis: '', loss: null, lossBasis: '', applicability: 'UNKNOWN', reason: '', configurationCondition: '', substitutionRequirement: '', routingOccurrenceId: null, note: '', legacyRowId: null }) }
async function findSites() { await run(async check => { sites.value = []; const values = result(await engineeringApi.siteChoices('')); check(); sites.value = values.filter(s => s.enabled) }) }
function chooseSite(selected: string) { if (!body.value) return; body.value.siteRef = selected ? copy(sites.value.find(s => key(s.reference) === selected)?.reference ?? body.value.siteRef) : null }
async function findRoutes() { const b = body.value; if (!b) return; await run(async check => { routes.value = []; const values = result(await routingApi.list(b.revisionOrigin.id)); check(); routes.value = values.filter(r => r.isCurrent && key(r.body.productRef) === key(b.productRef)) }) }
function chooseRouting(selected: string) { if (!body.value) return; body.value.routingRef = selected ? copy(routes.value.find(r => key(r.reference) === selected)?.reference ?? body.value.routingRef) : null }
async function findItems(target: number) { const kind = itemKind.value; await run(async check => { if (target === 1) { items.value = []; usages.value = []; usageChoice.value = ''; usageQueried.value = false } const values = result(await bomApi.items(kind, itemSearch.value, target)); check(); items.value.push(...values); itemPage.value = target; moreItems.value = values.length === 20 }) }
function chooseItem(line: BomOccurrence, selected: string) { if (!selected) line.itemRef = null; else { const item = items.value.find(i => key(i.reference) === selected); if (item) line.itemRef = copy(item.reference) } }
async function findUnits(target: number) { await run(async check => { if (target === 1) units.value = []; const values = result(await uomApi.list(unitSearch.value, target)); check(); units.value.push(...values.filter(u => u.isCurrent && u.profile.enabled)); unitPage.value = target; moreUnits.value = values.length === 20 }) }
function chooseUnit(line: BomOccurrence, selected: string) { if (!selected) line.unitRef = null; else { const unit = units.value.find(u => key(u.reference) === selected); if (unit) line.unitRef = copy(unit.reference) } }
async function findUsage(target: number) { const reference = items.value.find(i => key(i.reference) === usageChoice.value)?.reference; if (!reference) return; await run(async check => { usages.value = []; usageQueried.value = false; const values = result(await bomApi.whereUsed(reference, target)); check(); usages.value = values; usagePage.value = target; usageQueried.value = true }) }
async function findMappings() { const product = body.value?.productRef; if (!product) return; await run(async check => { mappings.value = []; mappingChoice.value = ''; preview.value = null; const values = result(await engineeringApi.mappings(product.id)); check(); mappings.value = values.filter(m => m.canAdoptIdentitySite && key(m.candidate.engineeringRef) === key(product)) }) }
async function previewLegacy() { const mapping = mappings.value.find(m => key(m.reference) === mappingChoice.value); if (!mapping) return; await run(async check => { preview.value = null; const value = result(await bomApi.legacy(mapping.reference)); check(); preview.value = value }) }
function adoptLegacy() { if (!body.value || !preview.value || locked.value || !canWrite.value) return; adopted.value = copy(preview.value); body.value.occurrences = copy(preview.value.suggestedOccurrences); body.value.siteRef = copy(mappings.value.find(m => key(m.reference) === key(preview.value!.mappingRef))?.candidate.siteRef ?? null); notice.value = '原件已放入草稿，请逐位置核对材料、单位和用量依据。' }
async function save() { const s = scope.value, draft = body.value; if (!s || !draft || !canWrite.value || pending.value) return
  const command: Omit<BomCommand, 'operationId'> = { bomId: id.value, action: current.value ? 'REVISE' : 'CREATE', expectedVersion: current.value?.reference.version ?? null, expectedEtag: current.value?.etag ?? null, body: copy(draft), reason: reason.value, legacyMappingRef: adopted.value?.mappingRef ?? null, legacyDigest: adopted.value?.digest ?? null }
  await run(async check => { const guard = () => { check(); if (!canWrite.value) throw new Error('当前无权保存结构。') }; await saveBom(s, command.bomId, guard, operationId => bomApi.save({ ...command, operationId })); check(); const saved = result(await bomApi.read(command.bomId)); check(); setCurrent(saved); rows.value = []; const values = result(await bomApi.list()); check(); rows.value = values; page.value = 1; notice.value = '结构版本已保存，评审与冻结仍待完成。' })
}
async function recover(close: boolean) { const s = scope.value; if (!s) return; await run(async check => { const original = await resolveBom(s, close, check); check(); if (original.state === 'COMMITTED') clearEditor(); notice.value = original.state === 'COMMITTED' ? '原操作已提交，请重新打开结构。' : original.state === 'CLOSED' ? '原操作已结束，可以继续编辑。' : '结果仍未知，请继续查询或结束未提交操作。' }) }
async function readHistory() { const value = current.value; if (!value) return; await run(async check => { history.value = null; const saved = result(await bomApi.read(value.reference.id, historyVersion.value)); check(); history.value = saved }) }
async function readDiff() { const value = current.value; if (!value) return; await run(async check => { diff.value = null; const saved = result(await bomApi.diff(value.reference.id, beforeVersion.value, afterVersion.value)); check(); diff.value = saved }) }
function clear() { generation++; busy.value = false; clearPrivate(); scope.value = null; pending.value = null; error.value = ''; notice.value = '' }
function identityChanged() { clear(); if (authenticationCanRead()) void reload() }
function storage(e: StorageEvent) { if (e.key?.startsWith('cp6_engineering_bom_operation_v1:')) { try { syncPending() } catch { error.value = '原操作记录异常，请保留记录。' } } }
watch(canRead, allowed => { if (!allowed) clear() })
onMounted(() => { window.addEventListener(AUTH_EVENT, identityChanged); window.addEventListener('storage', storage); void reload() })
onBeforeUnmount(() => { live = false; generation++; clearPrivate(); window.removeEventListener(AUTH_EVENT, identityChanged); window.removeEventListener('storage', storage) })
</script>
