.bom-page{display:grid;gap:18px;padding:24px;color:var(--el-text-color-primary)}header,.inline,nav{display:flex;gap:12px;align-items:center;flex-wrap:wrap}header{justify-content:space-between}section,.occurrence{padding:18px;border:1px solid var(--el-border-color);border-radius:8px;background:var(--el-bg-color)}.occurrence{margin:18px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}label{display:grid;gap:6px;margin:8px 0}input,select,textarea,button{font:inherit;padding:8px;border:1px solid var(--el-border-color);border-radius:4px;color:inherit;background:var(--el-bg-color);max-width:100%;box-sizing:border-box}button{margin:4px;cursor:pointer}button:disabled{opacity:.5;cursor:default}fieldset{border:0;padding:0}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:12px;border-bottom:1px solid var(--el-border-color)}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:400px;overflow:auto}[role=alert]{color:var(--el-color-danger)}:focus-visible{outline:2px solid var(--el-color-primary);outline-offset:2px}@media(max-width:600px){.bom-page{padding:12px}section,.occurrence{padding:12px}}
</style>
